/**
 * Shape of the raw JSON files on disk. The interesting payload is in
 * `results[0]` (and most callers further drill into `results[0].data`).
 *
 * Some entries omit the `results` wrapper, in which case the file root is
 * itself the country payload — `PapayaService` falls back to the file root
 * in that case.
 */
export interface PapayaCountryFile {
  results?: Array<{
    data?: unknown
    [key: string]: unknown
  }>
  data?: unknown
  [key: string]: unknown
}

